namespace Bnomei;

use Kirby\Toolkit\Str;

final class CacheBenchmark
{
    private static function benchmark($cache, int $seconds = 1, $count = 1000, $contentLength = 128, $writeRatio = 0.1): array
    {
        $readTimes = [];
        $writeTimes = [];
        $hits = 0;

        for ($i = 0; $i < $count; $i++) {
            $key = 'key_' . $i;
            $content = Str::random($contentLength);
            $start = microtime(true);

            if ($i < $count * $writeRatio) {
                $cache->set($key, $content);
                $writeTimes[] = microtime(true) - $start;
            } else {
                if ($cache->get($key) === $content) {
                    $hits++;
                }
                $readTimes[] = microtime(true) - $start;
            }
        }

        $averageReadTime = array_sum($readTimes) / count($readTimes);
        $averageWriteTime = array_sum($writeTimes) / count($writeTimes);
        $hitRatio = $hits / ($count * (1 - $writeRatio));

        return [
            'averageReadTime' => $averageReadTime,
            'averageWriteTime' => $averageWriteTime,
            'hitRatio' => $hitRatio,
        ];
    }
}

