function recursiveChmod(string $directory, int $mode): void {
    $iterator = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($directory, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::SELF_FIRST
    );

    foreach ($iterator as $item) {
        if ($item->isDir()) {
            chmod($item, $mode);
            echo "Changed permissions of directory: " . $item->getPathname() . PHP_EOL;
        } else {
            chmod($item, $mode);
            echo "Changed permissions of file: " . $item->getPathname() . PHP_EOL;
        }
    }
}

