use loophp\phptree\Exporter\Graph;
use loophp\phptree\Node\AttributeNode;
use loophp\phptree\Node\ValueNode;

function exportTreeToGraphviz($tree): string
{
    $graph = new Graph();

    // Recursively add nodes to the graph
    function addNodesToGraph($graph, $node)
    {
        if ($node instanceof AttributeNode) {
            $graph->node($node->getValue())->setAttribute('shape', 'box');
            foreach ($node->getChildren() as $child) {
                $graph->edge($node->getValue(), $child->getValue());
                addNodesToGraph($graph, $child);
            }
        } elseif ($node instanceof ValueNode) {
            $graph->node($node->getValue())->setAttribute('shape', 'ellipse');
        }
    }

    addNodesToGraph($graph, $tree);

    return (string) $graph;
}

