function php_input_sanitizer($value){
    // Check if magic_quotes_gpc is disabled
    if(!get_magic_quotes_gpc()){
        // Escape special characters if magic_quotes_gpc is disabled
        $value = addslashes($value);
    }

    // Sanitize the input to prevent XSS attacks
    $value = htmlspecialchars($value, ENT_QUOTES, 'UTF-8');

    return $value;
}

function flattenArray($input, $prefix = '') {
    $result = [];
    foreach ($input as $key => $value) {
        if (is_array($value)) {
            $result = array_merge($result, flattenArray($value, $prefix . $key . '_'));
        } else {
            $result[$prefix . $key] = $value;
