class CouponGenerator {
    private $generatedCodes = [];

    public function generateCodes($count, $length) {
        $generated = 0;
        while ($generated < $count) {
            $code = $this->generateRandomCode($length);
            if (!in_array($code, $this->generatedCodes)) {
                $this->generatedCodes[] = $code;
                $generated++;
            }
        }
