public function addexcuse(Request $request)
{
    $totalDays = 0;
    $excuses = $request->excuses;

    foreach ($excuses as $excuseData) {
        $excuseDate = new DateTime($excuseData['excuseDate']);
        $cancelDate = new DateTime($excuseData['cancelDate']);
        $daysDifference = $excuseDate->diff($cancelDate)->days;
        $totalDays += $daysDifference;
    }

