function paginateSignals($signals) {
    $paginatedResults = [];
    foreach ($signals as $signal) {
        $totalSignals = $signal['totalSignals'];
        $page = $signal['page'];
        $perPage = $signal['perPage'];

        $startIndex = ($page - 1) * $perPage;
        $endIndex = min($startIndex + $perPage, $totalSignals);

        $paginatedResults[] = array_slice(range(1, $totalSignals), $startIndex, $endIndex - $startIndex);
    }
    return $paginatedResults;
}

