    public function __construct($orderType)
    {
        $this->orderType = $orderType;
    }

    public function getOrderType()
    {
        return $this->orderType;
    }

    /**
     * Calculate the conditional close order price based on certain conditions
     * 
     * @param float $currentPrice The current price of the asset
     * @param float $targetPrice The target price for the asset
     * @param string $direction The direction of the trade (e.g., 'buy' or 'sell')
     * 
     * @return float The conditional close order price
     */
    public function calculateConditionalCloseOrderPrice($currentPrice, $targetPrice, $direction)
    {
        if ($direction === 'buy') {
            return $currentPrice > $targetPrice ? $currentPrice : $targetPrice;
        } elseif ($direction === 'sell') {
            return $currentPrice < $targetPrice ? $currentPrice : $targetPrice;
        } else {
