function filterMovies(array $movies, array $filters): array {
    if (empty($filters)) {
        return $movies;
    }

    $filteredMovies = $movies;

    if (isset($filters['title'])) {
        $filteredMovies = array_filter($filteredMovies, function ($movie) use ($filters) {
            return stripos($movie['title'], $filters['title']) !== false;
        });
    }

    if (isset($filters['year'])) {
        $filteredMovies = array_filter($filteredMovies, function ($movie) use ($filters) {
            return $movie['year'] == $filters['year'];
        });
    }

    return array_values($filteredMovies);
}

function parseAnnotations(string $class): array
{
    $reflectionClass = new ReflectionClass($class);
    $methods = $reflectionClass->getMethods();
    $result = [];

    foreach ($methods as $method) {
        $annotations = $method->getDocComment();
        preg_match('/@group\s+([^\s]+)/', $annotations, $matches);
        $group = isset($matches[1]) ? $matches[1] : 'No Group';
        $methodName = $method->getName();
        $result[$group][] = $methodName;
    }

    return $result;
}

