class SudokuSolver {
    private $sudoku;

    public function __construct($initialGrid) {
        $this->sudoku = $initialGrid;
    }

    public function solve() {
        $emptyCell = $this->findEmptyCell();
        if (!$emptyCell) {
            return true; // Puzzle solved
        }

        list($row, $col) = $emptyCell;

        for ($num = 1; $num <= 9; $num++) {
            if ($this->isSafe($row, $col, $num)) {
                $this->sudoku[$row][$col] = $num;

                if ($this->solve()) {
                    return true;
                }

                $this->sudoku[$row][$col] = 0; // Backtrack
            }
        }

        return false; // No solution exists
    }

    private function findEmptyCell() {
        for ($row = 0; $row < 9; $row++) {
            for ($col = 0; $col < 9; $col++) {
                if ($this->sudoku[$row][$col] === 0) {
                    return [$row, $col];
                }
            }
        }
        return false; // No empty cell
    }

    private function isSafe($row, $col, $num) {
        return !$this->usedInRow($row, $num) &&
               !$this->usedInCol($col, $num) &&
               !$this->usedInBox($row - $row % 3, $col - $col % 3, $num);
    }

    private function usedInRow($row, $num) {
        return in_array($num, $this->sudoku[$row]);
    }

    private function usedInCol($col, $num) {
        for ($row = 0; $row < 9; $row++) {
            if ($this->sudoku[$row][$col] === $num) {
                return true;
            }
        }
        return false;
    }

    private function usedInBox($startRow, $startCol, $num) {
        for ($row = 0; $row < 3; $row++) {
            for ($col = 0; $col < 3; $col++) {
                if ($this->sudoku[$row + $startRow][$col + $startCol] === $num) {
                    return true;
                }
            }
        }
        return false;
    }

    public function getSolvedSudoku() {
        return $this->sudoku;
    }
}

