        preg_match_all('/\/\*\*(.*?)\*\//s', $phpCode, $matches); // Match PHPDoc comments

        foreach ($matches[1] as $comment) {
            preg_match_all('/@(\w+)\(([^)]+)\)/', $comment, $annotationMatches); // Match annotation key-value pairs
            foreach ($annotationMatches[1] as $index => $key) {
                $annotations[$key] = trim($annotationMatches[2][$index]);
            }
        }

        return $annotations;
    }
}

