            $artistName = $artist->getElementsByTagName('Name')->item(0)->nodeValue;
            $albums = $artist->getElementsByTagName('Album');
            $artistData = [
                "artist" => $artistName,
                "albums" => []
            ];
            foreach ($albums as $album) {
                $albumTitle = $album->getElementsByTagName('Title')->item(0)->nodeValue;
                $tracks = $album->getElementsByTagName('Track');
                $trackList = [];
                foreach ($tracks as $track) {
                    $trackList[] = $track->getElementsByTagName('Title')->item(0)->nodeValue;
                }
                $artistData["albums"][] = [
                    "title" => $albumTitle,
                    "tracks" => $trackList
                ];
            }
            $library[] = $artistData;
        }
        return $library;
    }
}

