class RationalNumber {
    private $numerator;
    private $denominator;

    public function __construct($numerator, $denominator) {
        $gcd = $this->gcd($numerator, $denominator);
        $this->numerator = $numerator / $gcd;
        $this->denominator = $denominator / $gcd;
    }

    public function add(RationalNumber $other) {
        $newNumerator = $this->numerator * $other->denominator + $other->numerator * $this->denominator;
        $newDenominator = $this->denominator * $other->denominator;
        return new RationalNumber($newNumerator, $newDenominator);
    }

    public function subtract(RationalNumber $other) {
        $newNumerator = $this->numerator * $other->denominator - $other->numerator * $this->denominator;
        $newDenominator = $this->denominator * $other->denominator;
        return new RationalNumber($newNumerator, $newDenominator);
    }

    public function multiply(RationalNumber $other) {
        $newNumerator = $this->numerator * $other->numerator;
        $newDenominator = $this->denominator * $other->denominator;
        return new RationalNumber($newNumerator, $newDenominator);
    }

    public function divide(RationalNumber $other) {
        $newNumerator = $this->numerator * $other->denominator;
        $newDenominator = $this->denominator * $other->numerator;
        return new RationalNumber($newNumerator, $newDenominator);
    }

    public function toString() {
        if ($this->denominator === 1) {
            return (string) $this->numerator;
        } else {
            return sprintf('%d/%d', $this->numerator, $this->denominator);
        }
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $temp = $b;
            $b = $a % $b;
            $a = $temp;
        }
        return abs($a);
    }
}

class DataRenderer implements DataInterface {
    public function render(DataInterface $data): string {
        if (is_int($data)) {
            return (string)$data;
        } elseif (is_string($data)) {
            return $data;
        } elseif (is_array($data)) {
            return json_encode($data);
        } elseif (is_object($data)) {
            if (method_exists($data, '__toString')) {
                return $data->__toString();
            } else {
                return get_class($data) . ' object';
            }
        } else {
            return 'Unsupported data type';
        }
    }
}

