function extractControllerActions($phpCode)
{
    $matches = [];
    preg_match_all('/@Route\("(.*?)"\s*,\s*name="(.*?)"\)/', $phpCode, $matches, PREG_SET_ORDER);

    $actionNames = [];
    foreach ($matches as $match) {
        $actionName = lcfirst(str_replace('Action', '', substr($match[2], 0, -6)));
        $actionNames[] = $actionName;
    }

    return $actionNames;
}

