    private $registeredWorkers = [];

    public function registerWorker(string $workerName, string $workerClass) {
        $this->registeredWorkers[$workerName] = $workerClass;
    }

    public function bootWorker(string $workerName) {
        if (array_key_exists($workerName, $this->registeredWorkers)) {
            $workerClass = $this->registeredWorkers[$workerName];
            if (class_exists($workerClass)) {
                $worker = new $workerClass();
                $worker->performTask();
            } else {
                throw new Exception("Worker class not found: $workerClass");
            }
        } else {
