function calculateTimeDifference($timestamp) {
    $now = new DateTime();
    $transactionTime = new DateTime($timestamp);
    $interval = $now->diff($transactionTime);

    $timeDifference = '';
    if ($interval->y > 0) {
        $timeDifference = $interval->y . ' year' . ($interval->y > 1 ? 's' : '');
    } elseif ($interval->m > 0) {
        $timeDifference = $interval->m . ' month' . ($interval->m > 1 ? 's' : '');
    } elseif ($interval->d > 0) {
        $timeDifference = $interval->d . ' day' . ($interval->d > 1 ? 's' : '');
    } elseif ($interval->h > 0) {
        $timeDifference = $interval->h . ' hour' . ($interval->h > 1 ? 's' : '');
    } elseif ($interval->i > 0) {
        $timeDifference = $interval->i . ' minute' . ($interval->i > 1 ? 's' : '');
    } else {
        $timeDifference = 'just now';
    }

    return $interval->invert ? $timeDifference . ' ago' : $timeDifference . ' from now';
}

