class ServiceTokenManager
{
    private $serviceTokens = [];

    public function addToken($token)
    {
        $this->serviceTokens[] = $token;
    }

    public function removeToken($token)
    {
        $index = array_search($token, $this->serviceTokens);
        if ($index !== false) {
            array_splice($this->serviceTokens, $index, 1);
        }
    }

    public function hasToken($token)
    {
        return in_array($token, $this->serviceTokens);
    }

