function calculateQuartilesAndMax(array $data): array {
    sort($data);
    $count = count($data);

    $q1_index = (int)($count / 4);
    $q2_index = (int)($count / 2);
    $q3_index = (int)($count * 3 / 4);

    $q1 = $count % 2 == 0 ? ($data[$q1_index - 1] + $data[$q1_index]) / 2 : $data[$q1_index];
    $q2 = $count % 2 == 0 ? ($data[$q2_index - 1] + $data[$q2_index]) / 2 : $data[$q2_index];
    $q3 = $count % 2 == 0 ? ($data[$q3_index - 1] + $data[$q3_index]) / 2 : $data[$q3_index];
    $max = max($data);

    return [
        'q1' => (float)$q1,
        'q2' => (float)$q2,
        'q3' => (float)$q3,
        'max' => (int)$max
    ];
}

