code:
function reverseMigrations(string $input): string {
    $upIndex = strpos($input, 'public function up()');
    $downIndex = strpos($input, 'public function down()');

    if ($upIndex !== false && $downIndex !== false) {
        $upMethod = substr($input, $upIndex, $downIndex - $upIndex);
        $downMethod = substr($input, $downIndex);

        $reversedContent = str_replace($upMethod, '', $input);
        $reversedContent = str_replace($downMethod, '', $reversedContent);

        $reversedContent = str_replace('}', '', $reversedContent);
