function extractConstants(string $phpCode): array {
    $constants = [];
    $tokens = token_get_all($phpCode);

    $inConstantDefinition = false;
    $constantName = '';

    foreach ($tokens as $token) {
        if (is_array($token)) {
            if ($token[0] === T_CONST) {
                $inConstantDefinition = true;
            } elseif ($inConstantDefinition && $token[0] === T_STRING) {
                $constantName = $token[1];
            }
        } else {
            if ($inConstantDefinition && $token === '=') {
                $inConstantDefinition = false;
                $constants[] = $constantName;
            }
        }
    }

    return $constants;
}

