protected static function fillObjectProperties(array $value, ReflectionClass $ref)
{
    $constructArgs = $value['construct'] ?? [];
    unset($value['construct']);

    $obj = $ref->newInstanceArgs($constructArgs);

    foreach ($value as $k => $v) {
        if ($ref->hasProperty($k)) {
            $property = $ref->getProperty($k);
            $property->setAccessible(true);
            $property->setValue($obj, $v);
        }
    }

    return $obj;
}

