class CSVHandler {
    private $filename;
    private $delimiter;
    private $enclosure;
    private $escape;
    private $showHeaders;
    private $position;

    public function __construct($filename, $delimiter, $enclosure, $escape, $showHeaders) {
        $this->filename    = $filename;
        $this->delimiter   = $delimiter;
        $this->enclosure   = $enclosure;
        $this->escape      = $escape;
        $this->showHeaders = $showHeaders;
        $this->position    = 0;

        if (is_file($filename)) {
            throw new \RuntimeException(sprintf('The file %s already exists', $filename));
        }
    }

    public function readCSV($skipHeaders) {
        $rows = [];
        if (($handle = fopen($this->filename, 'r')) !== false) {
            if ($skipHeaders && $this->showHeaders) {
                fgetcsv($handle, 0, $this->delimiter, $this->enclosure, $this->escape);
            }
            while (($data = fgetcsv($handle, 0, $this->delimiter, $this->enclosure, $this->escape)) !== false) {
                $rows[] = $data;
            }
            fclose($handle);
        }
        return $rows;
    }
}

