class CookieManager {
    private $cookies = [];

    public function addCookie($cookie) {
        if (!is_string($cookie) && !($cookie instanceof CookieInterface)) {
            throw new CookieException("Invalid cookie type");
        }
        $this->cookies[] = $cookie;
    }

    public function removeCookie($cookie) {
        $key = array_search($cookie, $this->cookies);
        if ($key !== false) {
