code:
protected function getIndependentTypes(array $types): array {
    $dependencies = [];
    $independentTypes = [];

    // Create a map of dependencies for each type
    foreach ($types as $type) {
        $dependencies[$type] = [];
    }

    // Identify dependencies for each type
    foreach ($types as $type) {
        $matches = [];
        preg_match_all('/\b' . implode('\b|\b', $types) . '\b/', $type, $matches);
        $dependencies[$type] = array_unique($matches[0]);
    }

    // Identify independent types
    foreach ($types as $type) {
        $dependent = false;
        foreach ($dependencies as $dependency) {
            if (in_array($type, $dependency)) {
                $dependent = true;
                break;
            }
        }
        if (!$dependent) {
            $independentTypes[] = $type;
        }
    }

    return $independentTypes;
}

