public function processParams()
{
    if (empty($this->params)) {
        return [];
    }

    $numericValues = array_filter($this->params, 'is_numeric');
    $stringValues = array_filter($this->params, 'is_string');

    if (count($numericValues) == count($this->params)) {
        return array_sum($numericValues);
    } elseif (count($stringValues) == count($this->params)) {
        return implode('', $stringValues);
    } else {
