public function getString(array $templateData, array $contents, array $options = []) :string {
    $result = '';

    // Iterate through the template data
    foreach ($templateData as $placeholder => $templateValue) {
        // Check if the placeholder exists in the contents array
        if (array_key_exists($placeholder, $contents)) {
            // Replace the placeholder with the corresponding content
            $result .= str_replace("{{$placeholder}}", $contents[$placeholder], $templateValue);
        } else {
            // If the placeholder does not exist in the contents array, use the original template value
            $result .= $templateValue;
        }
    }

    return $result;
}

