class TimeConverter {
    const DEFAULT_PRECISION = 2;

    public static function monthsToDays($fraction, $precision = self::DEFAULT_PRECISION, $daysPerMonth) {
        if ($precision < 0) {
            throw new InvalidArgumentException('Precision cannot be negative');
        }

        $days = $fraction * $daysPerMonth; // Convert fraction of a month to days
        $multiplier = pow(10, $precision);
        $roundedDays = round($days * $multiplier) / $multiplier; // Round to specified precision

        return $roundedDays;
    }
}

