public function processQueryBlock($queryBlock, $query) {
    $logicalOperator = $queryBlock->and_or;
    $conditions = $queryBlock->conditions;

    $query->where(function ($query) use ($conditions, $logicalOperator) {
        foreach ($conditions as $condition) {
            if ($logicalOperator === 'and') {
                $query->where($condition['column'], $condition['operator'], $condition['value']);
            } elseif ($logicalOperator === 'or') {
                $query->orWhere($condition['column'], $condition['operator'], $condition['value']);
            }
        }
    });
}

