public function autoLinkEntities($tweet = null, $entities = null)
{
    // Iterate through each entity type
    foreach ($entities as $entityType => $entityDetails) {
        // Iterate through each entity detail
        foreach ($entityDetails as $entity) {
            $start = $entity['start'];
            $end = $entity['end'];
            $link = '';

            // Determine the link based on the entity type
            switch ($entityType) {
                case 'urls':
                    $link = "<a href='{$entity['url']}'>" . substr($tweet, $start, $end - $start) . "</a>";
                    break;
                case 'hashtags':
                    $link = "<a href='https://twitter.com/hashtag/{$entity['tag']}'>#" . substr($tweet, $start, $end - $start) . "</a>";
                    break;
                // Additional cases for other entity types
            }

            // Replace the entity with the generated link in the tweet content
            $tweet = substr_replace($tweet, $link, $start, $end - $start);
        }
    }

    return $tweet;
}

