function dotProduct(array $v): int {
    // Check if vectors have equal length
    $vCount = count($v);
    if ($vCount < 2) {
        throw new LengthException("At least two vectors are required for dot product calculation");
    }

    $firstVectorLength = count($v[0]);
    for ($i = 1; $i < $vCount; $i++) {
        if (count($v[$i]) != $firstVectorLength) {
            throw new LengthException("The array length is not the same");
        }
    }

    // Check if there is at least one element for each array
    foreach ($v as $vector) {
        if (empty($vector)) {
            throw new LengthException("Each array must contain at least 1 element");
        }
    }

    // Calculate the dot product
    $dotProduct = 0;
    $vectorLength = count($v[0]);
    for ($i = 0; $i < $vectorLength; $i++) {
        $product = 1;
        foreach ($v as $vector) {
            $product *= $vector[$i];
        }
        $dotProduct += $product;
    }

    return $dotProduct;
}

