public function __construct(Request $request, EntityRepository $repository, $paginationPath, $defaultOrderField, $pageSize)
{
    $this->pageSize = $pageSize;
    $this->paginationPath = $paginationPath;

    // Get the current page from the request, default to 1 if not provided
    $this->page = $request->query->getInt('page', 1);

    // Get the order field from the request, default to the provided default order field
    $this->orderField = $request->query->get('orderField', $defaultOrderField);

    // Get the order direction from the request, default to 'asc'
    $this->orderDirection = $request->query->get('orderDirection', 'asc');

    // Calculate the last page based on the total count of items in the repository and the page size
    $totalCount = $repository->getTotalCount();
    $this->lastPage = ceil($totalCount / $this->pageSize);

    // Ensure the current page is within valid bounds
    $this->page = max(1, min($this->page, $this->lastPage));
}

public function getData()
{
    // Retrieve the paginated data from the repository based on the current page, order field, and order direction
    $offset = ($this->page - 1) * $this->pageSize;
    $this->data = $repository->getPaginatedData($offset, $this->pageSize, $this->orderField, $this->orderDirection);

    return $this->data;
}

